func (this *Link) ParseMnemonics(buffer []uint16, start int32, end int32, result *jrt.StringBuilder) int32 {
	var mnemonic int32 = -1
	var index int32 = start
	for index < end {
		if int32(buffer[index]) == int32('&') {
			if index+1 < end && int32(buffer[index+1]) == int32('&') {
				result.Append(uint16(buffer[index]))
				index++
			} else {
				mnemonic = result.Length()
			}
		} else {
			result.Append(uint16(buffer[index]))
		}
		index++
	}
	return mnemonic
}

